<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api} from '@/api/client'
interface Profile{email:string;nickname:string;avatar_url?:string|null}
interface Activity{likes:string[];bookmarks:string[];comments:Array<{id:number;article_slug:string;content:string;created_at:string}>}
const profile=ref<Profile|null>(null),activity=ref<Activity|null>(null),error=ref('')
onMounted(async()=>{try{const [p,a]=await Promise.all([api.get('/api/users/me'),api.get('/api/users/me/activity')]);profile.value=p.data;activity.value=a.data}catch{error.value='暂时无法读取个人资料，请确认已登录。'}})
</script>
<template><div class="page-wrap profile"><span class="eyebrow">YOUR SPACE / ACCOUNT</span><h1 class="page-title">个人中心<span>。</span></h1><div v-if="profile" class="user-card"><div class="avatar">{{profile.nickname.slice(0,1)}}</div><div><h2>{{profile.nickname}}</h2><p>{{profile.email}}</p></div></div><div v-else class="notice">{{error||'正在读取资料...'}}</div><div v-if="activity" class="stats"><div><b>{{activity.comments.length}}</b><span>我的评论</span></div><div><b>{{activity.bookmarks.length}}</b><span>我的收藏</span></div><div><b>{{activity.likes.length}}</b><span>我的点赞</span></div></div><section v-if="activity" class="activity"><h2>最近评论</h2><article v-for="item in activity.comments" :key="item.id"><RouterLink :to="'/posts/'+item.article_slug+'/'">{{item.article_slug}}</RouterLink><p>{{item.content}}</p><time>{{new Date(item.created_at).toLocaleString('zh-CN')}}</time></article><p v-if="!activity.comments.length" class="muted">还没有发表过评论。</p></section></div></template>
<style scoped>.profile{max-width:900px;padding-top:75px}.page-title span{color:#8b79d6}.user-card{display:flex;align-items:center;gap:18px;margin:30px 0;padding:26px;border:1px solid #eae7f2;border-radius:18px;background:white}.avatar{width:58px;height:58px;display:grid;place-items:center;border-radius:19px;background:#efecff;color:#7767bc;font-size:28px}.user-card h2{margin:0 0 6px}.user-card p,.notice{color:#817d91;font-size:12px}.notice{margin:30px 0;padding:22px;border-radius:14px;background:#f5f3fc}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.stats div{display:grid;gap:5px;padding:20px;border:1px solid #eae7f2;border-radius:15px;background:white}.stats b{font-size:26px;color:#6e5cbd}.stats span,.muted{font-size:11px;color:#9993a7}.activity{margin-top:35px}.activity article{padding:15px 0;border-bottom:1px solid #eae7f2}.activity article a{color:#7665bd;font-size:12px}.activity article p{font-size:13px}.activity time{color:#aaa;font-size:10px}@media(max-width:650px){.stats{grid-template-columns:1fr}}</style>
